dashboard.definition:
{
    "title": "Security and Privacy",
    "description": "Security posture: HIS access log, Windows logons, ISE, logins on network devices and affected Cisco devices",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Time range",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        },
        "input_dept": {
            "type": "input.dropdown",
            "title": "Department",
            "options": {
                "items": [
                    {
                        "label": "All departments",
                        "value": "*"
                    },
                    {
                        "label": "Internal Medicine (INN)",
                        "value": "INN"
                    },
                    {
                        "label": "Cardiology (KAR)",
                        "value": "KAR"
                    },
                    {
                        "label": "Neurology (NEU)",
                        "value": "NEU"
                    },
                    {
                        "label": "Oncology (ONK)",
                        "value": "ONK"
                    },
                    {
                        "label": "General Surgery (CHI)",
                        "value": "CHI"
                    },
                    {
                        "label": "Trauma Surgery/Orthopedics (UCH)",
                        "value": "UCH"
                    },
                    {
                        "label": "Urology (URO)",
                        "value": "URO"
                    },
                    {
                        "label": "HNO",
                        "value": "HNO"
                    },
                    {
                        "label": "Anesthesia/OR (ANA)",
                        "value": "ANA"
                    },
                    {
                        "label": "Intensive Care (ICU)",
                        "value": "ICU"
                    },
                    {
                        "label": "Emergency Department (ZNA)",
                        "value": "ZNA"
                    },
                    {
                        "label": "Radiology (RAD)",
                        "value": "RAD"
                    },
                    {
                        "label": "Gynecology/Obstetrics (GYN)",
                        "value": "GYN"
                    },
                    {
                        "label": "Pediatrics (PAED)",
                        "value": "PAED"
                    },
                    {
                        "label": "Psychiatry (PSY)",
                        "value": "PSY"
                    }
                ],
                "token": "dept",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        }
    },
    "dataSources": {
        "ds_audit": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"sakh:kis:audit\" department=\"$dept$\"\n| fields Time _time action break_the_glass btg_reason count department h m patient_id result role user ward workstation",
                "enableSmartSources": true
            },
            "name": "KIS-Audit"
        },
        "ds_k_btg": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_audit",
                "query": "| where break_the_glass=\"true\" OR break_the_glass=1 | timechart span=1h count as \"Break-the-Glass\""
            }
        },
        "ds_k_fail": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_audit",
                "query": "| where result=\"Failed\" | timechart span=1h count as \"HIS logins failed\""
            }
        },
        "ds_k_win": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"WinEventLog\" EventCode=4625 | timechart span=1h count as \"Windows 4625\"",
                "enableSmartSources": true
            }
        },
        "ds_k_lock": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"WinEventLog\" EventCode=4740 | stats count as \"Account lockouts\"",
                "enableSmartSources": true
            }
        },
        "ds_k_net": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"cisco:ios\" \"LOGIN_SUCCESS\" NOT \"Source: 10.\" | stats count as \"External device logins\"",
                "enableSmartSources": true
            }
        },
        "ds_k_psirt": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"cisco:iq:advisory\" severity=\"Critical\" earliest=-7h | stats dc(hostname) as \"PSIRT critical\"",
                "enableSmartSources": true
            }
        },
        "ds_btg": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_audit",
                "query": "| where break_the_glass=\"true\" OR break_the_glass=1\n| eval Time=strftime(_time, \"%m/%d %H:%M\") | table Time user role department ward workstation patient_id btg_reason\n| rename user as User role as Role department as Department ward as Ward workstation as Workstation patient_id as Patient btg_reason as Justification"
            }
        },
        "ds_logins": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_audit",
                "query": "| where action=\"Login\" | timechart span=30m count by result"
            }
        },
        "ds_win": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"WinEventLog\" (EventCode=4625 OR EventCode=4740 OR EventCode=4672)\n| rex \"Account Name:\\\\s+(?<account>\\\\S+)\" | rex \"Source Network Address:\\\\s+(?<src>\\\\S+)\"\n| stats count as Count latest(_time) as t by EventCode account src ComputerName\n| eval Time=strftime(t, \"%m/%d %H:%M\"), Ereignis=case(EventCode=4625, \"Logon failed\", EventCode=4740, \"Account locked\", true(), \"Privileged logon\")\n| sort - Count | head 25 | table Time Ereignis account src ComputerName Count | rename account as Account src as Source ComputerName as Server",
                "enableSmartSources": true
            }
        },
        "ds_netlogin": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"cisco:ios\" (\"LOGIN_SUCCESS\" OR \"CONFIG_P\" OR \"WEBUI\") | rex \"^<\\d+>\\d+: (?<device>[^:]+): [^%]+%(?<facility>[A-Z0-9_]+)-(?<severity>\\d)-(?<mnemonic>[A-Z0-9_]+): (?<message_text>.*)\"\n| rex \"\\\\[user: (?<user>[^\\\\]]+)\\\\] \\\\[Source: (?<src>[^\\\\]]+)\\\\]\"\n| eval Time=strftime(_time, \"%m/%d %H:%M:%S\"), Assess=if(isnotnull(src) AND NOT cidrmatch(\"10.0.0.0/8\", src), \"suspicious\", \"internal\")\n| table Time device mnemonic user src Assess message_text | rename device as Device user as User src as Source message_text as Message | head 30",
                "enableSmartSources": true
            }
        },
        "ds_ssh": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"syslog\" \"Failed password\" | rex \"from (?<src>\\\\S+) port\" | timechart span=1h count by host",
                "enableSmartSources": true
            }
        },
        "ds_psirt": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"cisco:iq:advisory\" earliest=-7h | stats dc(hostname) as Devices by severity advisoryId | sort severity | rename severity as Severity advisoryId as Advisory",
                "enableSmartSources": true
            }
        },
        "ds_inc": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"snow:incident\" category=\"Security\" | stats latest(state) as Status latest(priority_label) as Priority latest(short_description) as Description latest(opened_at) as Opened by number | rename number as Incident",
                "enableSmartSources": true
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_clinic/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_clinic",
                        "dashboard": "kis_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_care": {
            "type": "splunk.image",
            "options": {
