                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#0b7fab"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 3,
                        "value": "#1e8a5a"
                    },
                    {
                        "from": 3,
                        "to": 8,
                        "value": "#c98a00"
                    },
                    {
                        "from": 8,
                        "value": "#c8253f"
                    }
